import test from "node:test";
import assert from "node:assert/strict";
import {planner} from "./replay.mjs";
import {Ledger} from "./common/ledger.mjs";
import {bookStudio, renewStudio} from "./services/studio.mjs";

const catalog = {default: 5, studios: new Map([["orchid", 8], ["iris", 3]])};
const booking = (id, extra = {}) => ({
  service: "studio", action: "book", id, tenant: "orchid", day: "2025-04-02",
  units: 7, ...extra
});

test("Studio applies tenant caps and preserves journal semantics", () => {
  const dispatch = planner(catalog);
  const first = booking("first");
  assert.deepEqual(dispatch(first), {status: "booked", id: "first", remaining: 1});
  assert.equal(dispatch(first).status, "replay");
  assert.equal(dispatch({...first, units: 6}).status, "conflict");
  assert.deepEqual(dispatch(booking("second", {units: 2})),
    {status: "full", id: "second", remaining: 1});
  assert.equal(dispatch(booking("tomorrow", {day: "2025-04-03"})).status, "booked");
  assert.equal(dispatch(booking("other", {tenant: "lily", units: 5})).status, "booked");
  assert.equal(dispatch(booking("iris-full", {tenant: "iris", units: 4})).status, "full");
  assert.equal(dispatch(booking("iris", {tenant: "iris", units: 3})).status, "booked");
  assert.equal(dispatch({...first, action: "cancel"}).status, "cancelled");
  assert.equal(dispatch(first).status, "cancelled");
  assert.equal(dispatch({...first, action: "cancel"}).status, "replay");
  assert.deepEqual(dispatch(booking("replacement", {units: 8})),
    {status: "booked", id: "replacement", remaining: 0});
  assert.deepEqual(dispatch({...first, action: "usage"}), {units: 8});
  const summary = dispatch({...first, action: "summary"});
  assert.equal(summary.events.filter(row => row.id === "first").length, 2);
  assert.ok(!summary.occupied.some(row => row.id === "first"));
});

test("renewals use Studio allocation while Archive keeps the default", () => {
  const dispatch = planner(catalog);
  dispatch(booking("source"));
  dispatch(booking("other", {day: "2025-05-02", units: 2}));
  const renewal = {service: "studio", action: "renew", previous: "source",
    id: "renewal", day: "2025-05-02"};
  assert.deepEqual(dispatch(renewal), {status: "full", id: "renewal", remaining: 6});
  dispatch({service: "studio", action: "cancel", id: "other"});
  assert.deepEqual(dispatch(renewal), {status: "booked", id: "renewal", remaining: 1});
  assert.equal(dispatch(renewal).status, "replay");
  assert.equal(dispatch({...renewal, units: 6}).status, "conflict");
  dispatch({service: "studio", action: "cancel", id: "source"});
  assert.deepEqual(dispatch({...renewal, id: "missing"}), {status: "missing", id: "source"});

  assert.equal(dispatch(booking("archive-full", {service: "archive"})).status, "full");
  dispatch(booking("archive-source", {service: "archive", units: 5}));
  assert.equal(dispatch({...renewal, service: "archive", previous: "archive-source",
    id: "archive-renewal", units: 6}).status, "full");
  dispatch(booking("fallback", {tenant: "lily", units: 5}));
  assert.equal(dispatch({...renewal, previous: "fallback", id: "fallback-renewal"}).status, "booked");
  assert.equal(dispatch({...renewal, previous: "fallback", id: "fallback-full", units: 6,
    day: "2025-06-02"}).status, "full");
});

test("Studio adapters honor supplied catalogs and imports remain unconditional", () => {
  const ledger = new Ledger(catalog);
  const request = booking("direct", {units: 8});
  assert.equal(bookStudio(ledger, request, catalog).status, "booked");
  assert.equal(renewStudio(ledger, {previous: "direct", id: "next", day: "2025-05-02"}, catalog).status, "booked");
  const dispatch = planner(catalog);
  assert.equal(dispatch(booking("backfill", {action: "import", units: 10})).status, "imported");
  assert.equal(dispatch(booking("backfill", {units: 10})).status, "replay");
  assert.deepEqual(dispatch(booking("new", {units: 1})), {status: "full", id: "new", remaining: 0});
});
EOF
